namespace RonSijm.FluidHumidifier.Factories.Glue;

public class InnerConnectionAuthenticationConfigurationFactory(Action<Humidifier.Glue.ConnectionTypes.AuthenticationConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypes.AuthenticationConfiguration>
{

    internal InnerConnectionOAuth2PropertiesFactory OAuth2PropertiesFactory { get; set; }

    internal InnerConnectionBasicAuthenticationCredentialsFactory BasicAuthenticationCredentialsFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypes.AuthenticationConfiguration Create()
    {
        var authenticationConfigurationResult = CreateAuthenticationConfiguration();
        factoryAction?.Invoke(authenticationConfigurationResult);

        return authenticationConfigurationResult;
    }

    private Humidifier.Glue.ConnectionTypes.AuthenticationConfiguration CreateAuthenticationConfiguration()
    {
        var authenticationConfigurationResult = new Humidifier.Glue.ConnectionTypes.AuthenticationConfiguration();

        return authenticationConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypes.AuthenticationConfiguration result)
    {
        base.CreateChildren(result);

        result.OAuth2Properties ??= OAuth2PropertiesFactory?.Build();
        result.BasicAuthenticationCredentials ??= BasicAuthenticationCredentialsFactory?.Build();
    }

} // End Of Class

